#include "tetris_v12_r2_lib.c"

typedef struct{unsigned long long n,nfull,offfull;double nbit,offbit;}HStat;
static void heval(const Medium*b,const LocalR*l,const PairR*p,int n,uint64_t seed){HStat hs[31];memset(hs,0,sizeof(hs));RNG r={seed};Game g;game_init(&g,rng_i(&r,7));Pilot po={0};for(int i=0;i<n;i++){if(!samp(&r,&g,&po)){i--;continue;}int h=hz(&g);if(h<1||h>30){i--;continue;}uint8_t cur[FRAME_BITS],coff[FRAME_BITS],tar[FRAME_BITS],o[OUT];render_bits(&g,cur);memcpy(coff,cur,FRAME_BITS);Game q=g;adv(&q,h);render_bits(&q,tar);for(int z=0;z<h;z++){predictv(b,l,p,cur,0,0,o);for(int j=0;j<OUT;j++)cur[j]=o[j];predictv(b,l,p,coff,0,1,o);for(int j=0;j<OUT;j++)coff[j]=o[j];}HStat*s=&hs[h];s->n++;s->nfull+=eqv(cur,tar,0,OUT);s->offfull+=eqv(coff,tar,0,OUT);int cn=0,cf=0;for(int j=0;j<OUT;j++){cn+=cur[j]==tar[j];cf+=coff[j]==tar[j];}s->nbit+=(double)cn/OUT;s->offbit+=(double)cf/OUT;}
 puts("h,n,normal_full,pairOff_full,normal_bit,pairOff_bit");for(int h=1;h<=30;h++)if(hs[h].n)printf("%d,%llu,%.3f,%.3f,%.4f,%.4f\n",h,hs[h].n,100.0*hs[h].nfull/hs[h].n,100.0*hs[h].offfull/hs[h].n,100.0*hs[h].nbit/hs[h].n,100.0*hs[h].offbit/hs[h].n);}
int main(int argc,char**argv){int nb=argc>1?atoi(argv[1]):15000,nl=argc>2?atoi(argv[2]):20000,np=argc>3?atoi(argv[3]):20000,ne=argc>4?atoi(argv[4]):3000;Medium b;med_init(&b);if(0)eval(&b,1,0);train(&b,nb,0x121000ULL);LocalR l;li(&l);PairR p;pi(&p);RNG r={0x122000ULL};Game g;game_init(&g,rng_i(&r,7));Pilot po={0};uint8_t in[FRAME_BITS],tar[FRAME_BITS];for(int t=0;t<nl;t++){pair(&r,&g,&po,t&1,in,tar);train_localr(&b,&l,in,tar);}for(int t=0;t<np;t++){pair(&r,&g,&po,t&1,in,tar);train_pair(&b,&l,&p,in,tar);}printf("writes=%llu,%llu,%llu\n",b.writes,l.writes,p.writes);heval(&b,&l,&p,ne,0x12EF00ULL);pf(&p);lf(&l);med_free(&b);return 0;}
